window.kbPageData["views/entry/k-01e62c91bad01ee7"] = {"key":"entry/k-01e62c91bad01ee7","state":{"route":"entry/k-01e62c91bad01ee7"},"node":{"id":"k-01e62c91bad01ee7","mode":"k","title":"间隔增长率","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["间隔增长率与相邻两期增长率的关系","间隔增长率的增长因子乘积关系"],"qs":["国考 2023 副省级 行测#131","国考 2023 行政执法 行测#126"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":2,"repeatPositions":0,"directorySummary":"间隔增长率是某期数值相对于隔一期的基期数值的增长率。若连续两期的增长率分别为 r₁ 和 r₂，则间隔增长率为 (1＋r₁)(1＋r₂)－1。","review":{"definition":"间隔增长率是某期数值相对于隔一期的基期数值的增长率。若连续两期的增长率分别为 r₁ 和 r₂，则间隔增长率为 (1＋r₁)(1＋r₂)－1。","explanation":"后一段的增长以前一段变化后的数值为基数，因此两段的增长倍数相乘。第131题中，2021年全国服装出口额是2019年的1.16倍，也是2020年的1.24倍，所以2020年比2019年的增长率为 1.16÷1.24－1≈－6.45%，即下降了不到10%，选D。","references":[],"evidence":"服装出口1702.8亿美元，同比增长24.0%，较2019年增长16.0%。","disposition":"独立词条","basis":"据原题和解析编释。","title":"间隔增长率","related":[],"examFocus":{"国考 2023 副省级 行测#131":"把2021年服装出口额相对2019年和2020年的增速换成出口额之比，再反推2020年相对2019年的增速。","国考 2023 行政执法 行测#126":"把2021年相对2019年的服装出口额之比写成两个相邻年份之比的乘积，再用已知增速反推缺少的那一项。"}},"readings":[{"origin":"k-01e62c91bad01ee7","title":"间隔增长率","qs":["国考 2023 副省级 行测#131"],"definition":"间隔增长率是某期数值相对于隔一期的基期数值的增长率。若连续两期的增长率分别为 r₁ 和 r₂，则间隔增长率为 (1＋r₁)(1＋r₂)－1。","explanation":"后一段的增长以前一段变化后的数值为基数，因此两段的增长倍数相乘。第131题中，2021年全国服装出口额是2019年的1.16倍，也是2020年的1.24倍，所以2020年比2019年的增长率为 1.16÷1.24－1≈－6.45%，即下降了不到10%，选D。","evidence":"服装出口1702.8亿美元，同比增长24.0%，较2019年增长16.0%。","doubt":"","references":[]},{"origin":"k-74991a7be3bc84ae","title":"间隔增长率","qs":["国考 2023 行政执法 行测#126"],"definition":"间隔增长率是跨过中间一期的两个时期之间的相对变化率。对同一指标，跨两期的增长因子（1＋间隔增长率）等于两个相邻期增长因子的乘积。","explanation":"把末期值与起期值的比值拆成「末期值÷中间期值」和「中间期值÷起期值」的乘积，中间期值就会约去。第126题中，2021年全国服装出口额较2019年增长16.0%，较2020年增长24.0%，因此2020年较2019年的增长率为 1.16÷1.24－1≈−6.45%，即下降了不到10%，选D。","evidence":"服装出口1702.8亿美元，同比增长24.0%，较2019年增长16.0%。","doubt":"","references":[]}]},"questions":{"国考 2023 副省级 行测#131":{"paper":"国考 2023 副省级 行测","n":131,"mod":"资料分析","src":["503793642e845de9795f.pdf",28],"asrc":["ecade1ff5af69283232e.pdf",41],"card":"22ccc8f4f628ebac3c15027c","links":[{"id":"k-01e62c91bad01ee7","role":"解题依据","why":"跨两期的增长因子等于两个相邻时期增长因子的乘积。"}]},"国考 2023 行政执法 行测#126":{"paper":"国考 2023 行政执法 行测","n":126,"mod":"资料分析","src":["857378cf496f27296500.pdf",27],"asrc":["d23139fe5a0fb3115135.pdf",40],"card":"d3fa1dd41baf7ff7167e4e06","links":[{"id":"k-01e62c91bad01ee7","role":"解题依据","why":"两年间隔的增长因子等于两个相邻年度增长因子的乘积，可用来反推缺失的年度增速。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-01e62c91bad01ee7":[["国考 2023 副省级 行测#131"],["国考 2023 行政执法 行测#126"]]}};
